-- Volcando estructura para tabla pos_sistema.products
CREATE TABLE IF NOT EXISTS `products` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `product_type` enum('simple','variable') NOT NULL DEFAULT 'simple',
  `name` varchar(255) NOT NULL,
  `description` text DEFAULT NULL,
  `sku` varchar(255) DEFAULT NULL,
  `barcode` varchar(255) DEFAULT NULL,
  `category_id` bigint(20) unsigned NOT NULL,
  `supplier_id` bigint(20) unsigned DEFAULT NULL,
  `cost_price` decimal(10,2) DEFAULT NULL,
  `avg_cost` decimal(10,2) NOT NULL DEFAULT 0.00,
  `sale_price` decimal(10,2) DEFAULT NULL,
  `measurement_unit` enum('unit','kg','g','m','cm','l','ml') NOT NULL DEFAULT 'unit' COMMENT 'Unidad de medida: unit=Unidades, kg=Kilogramos, g=Gramos, m=Metros, cm=Centímetros, l=Litros, ml=Mililitros',
  `allow_decimal` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Si true, permite cantidades decimales (ej: 1.5 kg). Si false, solo enteros (ej: 2 unidades)',
  `wholesale_price` decimal(10,2) DEFAULT NULL,
  `current_stock` int(11) NOT NULL DEFAULT 0,
  `min_stock` int(11) NOT NULL DEFAULT 5,
  `ideal_stock` int(11) NOT NULL DEFAULT 50,
  `total_sold` int(11) NOT NULL DEFAULT 0,
  `total_revenue` decimal(12,2) NOT NULL DEFAULT 0.00,
  `total_profit` decimal(12,2) NOT NULL DEFAULT 0.00,
  `last_sale_date` datetime DEFAULT NULL,
  `last_purchase_date` datetime DEFAULT NULL,
  `avg_discount_applied` decimal(5,2) NOT NULL DEFAULT 0.00,
  `days_to_sell_avg` int(11) NOT NULL DEFAULT 0,
  `max_stock` int(11) DEFAULT NULL,
  `unit` varchar(255) NOT NULL DEFAULT 'unidad',
  `manage_stock` tinyint(1) NOT NULL DEFAULT 1,
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `is_public` tinyint(1) NOT NULL DEFAULT 1,
  `public_description` text DEFAULT NULL,
  `public_image` varchar(255) DEFAULT NULL,
  `deactivated_by_category` tinyint(1) NOT NULL DEFAULT 0,
  `image_url` longtext DEFAULT NULL,
  `tags` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`tags`)),
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `main_supplier_id` bigint(20) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `products_sku_unique` (`sku`),
  UNIQUE KEY `products_barcode_unique` (`barcode`),
  KEY `products_active_index` (`active`),
  KEY `products_sku_index` (`sku`),
  KEY `products_barcode_index` (`barcode`),
  KEY `products_category_id_index` (`category_id`),
  KEY `products_current_stock_index` (`current_stock`),
  KEY `products_active_current_stock_index` (`active`,`current_stock`),
  KEY `products_min_stock_current_stock_index` (`min_stock`,`current_stock`),
  KEY `products_total_sold_last_sale_date_index` (`total_sold`,`last_sale_date`),
  KEY `products_supplier_id_foreign` (`supplier_id`),
  KEY `products_main_supplier_id_foreign` (`main_supplier_id`),
  KEY `idx_products_active` (`active`),
  KEY `idx_products_category` (`category_id`),
  KEY `idx_products_stock` (`current_stock`),
  KEY `products_is_public_active_index` (`is_public`,`active`),
  KEY `products_measurement_unit_index` (`measurement_unit`),
  CONSTRAINT `products_category_id_foreign` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON DELETE CASCADE,
  CONSTRAINT `products_main_supplier_id_foreign` FOREIGN KEY (`main_supplier_id`) REFERENCES `suppliers` (`id`),
  CONSTRAINT `products_supplier_id_foreign` FOREIGN KEY (`supplier_id`) REFERENCES `suppliers` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

